// narrate.mjs tarafından üretildi; elle düzenlemeyin. Motor: mbrola:tr1
window.VOICE = {"engine":"mbrola:tr1","gain":1.25,"lines":[{"id":"open-title","say":"Birinci kapı, ikinci bölüm: taşa kazınan mantık.","at":3.8,"dur":4.188,"marks":[0,1.361,2.821]},{"id":"recap-numbers","say":"Bir önceki bölümde, makinenin sayıları nasıl tuttuğunu konuştuk: her şey, var ile yok, bir ile sıfır dizileridir.","at":9.588,"dur":8.991,"marks":[0,1.7,5.056,6.147,7.295]},{"id":"recap-question","say":"Şimdi çok daha şaşırtıcı bir soruya geliyoruz: elektrik nasıl olur da düşünür?","at":19.579,"dur":5.814,"marks":[0,3.673]},{"id":"recap-bell","say":"Yanıt, bir kapı zilinden bile basittir.","at":26.393,"dur":3.008,"marks":[0,0.834]},{"id":"circuit-loop","say":"Önce küçük bir hatırlatma. Elektriğin bir lambayı yakabilmesi için, pilden çıkıp yeniden pile dönen, kesintisiz bir yol gerekir; buna devre denir.","at":31.401,"dur":11.798,"marks":[0,2.541,5.696,8.287,10.641]},{"id":"circuit-break","say":"Yol bir yerinden koptuğunda, akım durur ve lamba söner.","at":44.199,"dur":4.08,"marks":[0,2.217]},{"id":"circuit-switch","say":"Anahtar, bu yolu isteğimizle açıp kapatan küçük bir köprüdür. Işığı açmak der gibi, anahtar açık dediğimizde, akımın geçtiği konumu kastedeceğiz.","at":49.279,"dur":11.69,"marks":[0,1.031,5.177,7.139,9.261]},{"id":"circuit-bits","say":"Açık, bir; kapalı, sıfır. Lamba yanıyorsa bir, sönükse sıfır.","at":61.969,"dur":6.932,"marks":[0,0.844,1.723,2.695,3.952,5.75]},{"id":"and-setup","say":"Şimdi bir odada bir lamba ve iki anahtar olsun; adları A ile B. Anahtarları arka arkaya, tek bir hat üzerine bağlayalım.","at":70.701,"dur":9.312,"marks":[0,3.603,5.245,7.328]},{"id":"and-cases","say":"İkisi de kapalı: lamba sönük. Yalnız A açık: yine sönük. Yalnız B açık: yine sönük. İkisi de açık: lamba yanar.","at":81.013,"dur":11.427,"marks":[0,1.675,3.211,4.656,6.09,7.609,9.043,10.531]},{"id":"and-why","say":"Çünkü akımın tek bir yolu var, ve o yol iki anahtarın da içinden geçer; biri bile kapalıysa, yol kopar.","at":93.44,"dur":8.062,"marks":[0,2.394,5.489,7.253]},{"id":"and-name","say":"Bu düzeneğin adı, VE kapısıdır: A VE B açıksa, lamba yanar.","at":102.502,"dur":5.439,"marks":[0,1.493,3.04,4.543]},{"id":"and-gate","say":"Kapı denmesinin nedeni de şu: bu düzenekler, akımın geçip geçmeyeceğine karar verir; tıpkı açılıp kapanan bir kapı gibi.","at":108.391,"dur":9.448,"marks":[0,2.424,3.852,7.076]},{"id":"or-setup","say":"Şimdi aynı iki anahtarı yan yana, ayrı hatlara bağlayalım. Artık akımın iki yolu var.","at":119.839,"dur":6.597,"marks":[0,2.553,4.847]},{"id":"or-cases","say":"İkisi de kapalıyken lamba sönük. A açılınca yanar; B açılınca da yanar; ikisi birden açıkken de yanar.","at":127.436,"dur":8.561,"marks":[0,2.869,4.53,6.41]},{"id":"or-name","say":"Herhangi biri açıksa, lamba yanar. Bunun adı da VEYA kapısıdır.","at":136.997,"dur":5.396,"marks":[0,1.946,3.501]},{"id":"not-fridge","say":"Üçüncü bir düzenek daha kurabiliriz: girişi tersine çeviren bir düzenek. Buzdolabının içindeki ışığı düşünün. Kapı kapanırken küçük bir düğmeye bastırır, ve ışık söner; kapıyı açtığınızda düğme bırakılır, ışık yanar.","at":144.393,"dur":17.654,"marks":[0,2.832,5.859,9.059,12.422,13.991,16.756]},{"id":"not-name","say":"Anahtar açıkken lamba söner, kapalıyken yanar. Buna DEĞİL kapısı denir: bir girerse sıfır çıkar, sıfır girerse bir.","at":163.047,"dur":9.994,"marks":[0,2.426,4.34,6.464,8.643]},{"id":"not-three","say":"Hepsi bu kadar. VE, VEYA, DEĞİL. Bilişim dünyasının bütün mantığı, bu üç düzenekten kuruludur. Mühendisler onları, işte bu simgelerle çizer.","at":174.041,"dur":13.228,"marks":[0,1.76,2.482,3.329,4.468,7.163,9.724,11.476]},{"id":"why-pause","say":"Bir an durup düşünelim. Kurduğumuz şey, yalnızca elektrikle çalışan bir devre değildi; bir cümleyi elektriğe çevirmiş olduk.","at":189.469,"dur":9.855,"marks":[0,2.245,3.664,7.355]},{"id":"why-alarm","say":"Kapı açıksa VE alarm kuruluysa, sireni çal. Bu bir insan cümlesidir. Ama artık ona karşılık gelen bir devre kurabiliyoruz: iki anahtar, arka arkaya, ucunda siren.","at":200.324,"dur":13.954,"marks":[0,2.601,4.143,6.422,10.355,11.63,12.98]},{"id":"why-fire","say":"Yangın algılandıysa VEYA düğmeye basıldıysa, kapıları aç. Bu da bir insan cümlesidir; onun da devresi var: iki anahtar, yan yana.","at":215.278,"dur":11.036,"marks":[0,3.423,4.947,7.203,9.059,10.334]},{"id":"why-bridge","say":"İşte bilişimin sırrı burada yatar: mantıksal düşünme ile elektrik devresi arasında, birebir bir karşılık vardır. Bir kez bu köprü kurulunca, insanın kurabildiği her mantıklı cümle, elektrikle çalışan bir düzeneğe çevrilebilir.","at":227.314,"dur":17.595,"marks":[0,2.778,6.495,9.155,11.387,14.397]},{"id":"boole-who","say":"Bu köprünün matematiğini, on dokuzuncu yüzyılda İngiliz matematikçi George Boole kurmuştu; hiçbir makine yokken, tamamen kâğıt üzerinde.","at":247.109,"dur":10.424,"marks":[0,2.072,6.795,8.874]},{"id":"boole-algebra","say":"Cebir, harflerle hesap yapmak demektir. Boole bu hesabı sayılarla değil, doğru ile yanlışla yaptı: doğruya bir, yanlışa sıfır dedi. VE, onun için bir çarpmaydı; DEĞİL ise, birden çıkarmak.","at":258.533,"dur":17.198,"marks":[0,0.896,3.917,6.363,8.545,9.794,11.888,12.609,14.843,15.956]},{"id":"boole-shannon","say":"Yaklaşık yüz yıl sonra, bin dokuz yüz otuz yedide, Claude Shannon adında genç bir mühendis, Boole’un cebrinin elektrik anahtarlarıyla birebir örtüştüğünü fark etti.","at":276.731,"dur":12.302,"marks":[0,2.131,4.252,7.378]},{"id":"boole-lesson","say":"Kuramın, uygulamayı yüz yıl önceden beklediği bu hikâye, bunu ne zaman kullanacağım diye soran her öğrenciye anlatılmaya değer.","at":290.033,"dur":8.882,"marks":[0,1.031,4.439]},{"id":"table-intro","say":"Bir mantık kapısının davranışını göstermenin en açık yolu, bütün olasılıkları bir tabloya dökmektir. Buna doğruluk tablosu denir.","at":300.915,"dur":9.684,"marks":[0,4.334,7.765]},{"id":"table-read","say":"Solda girişler, sağda sonuç durur; her satır, bir durumdur. İki giriş varsa dört satır olur; ilk bölümdeki iki lambayı hatırlayın.","at":311.599,"dur":11.567,"marks":[0,1.586,3.485,4.681,6.26,9.015]},{"id":"table-and","say":"VE kapısında ikisi de gerekir: dört satırdan yalnızca birinde, ikisi de bir olduğunda, sonuç birdir.","at":324.166,"dur":8.164,"marks":[0,2.638,5.229,7.07]},{"id":"table-or","say":"VEYA kapısında biri yeter: sonuç, yalnızca ikisi de sıfırken sıfırdır.","at":333.33,"dur":5.832,"marks":[0,2.267,3.232]},{"id":"table-not","say":"DEĞİL kapısının tek girişi vardır; ne girerse, tersi çıkar.","at":340.162,"dur":5.084,"marks":[0,2.887,4.104]},{"id":"table-mult","say":"Bu tablolara mantığın çarpım tablosu demek yanlış olmaz. Hatta VE tablosu, gerçekten de bir çarpım tablosudur: sıfırla biri çarpın, aynı sonuçları bulursunuz. Ezberlenmesi gerekmez; bir kez kavranınca, zaten unutulmaz.","at":346.246,"dur":18.449,"marks":[0,4.38,6.087,9.161,11.085,13.523,15.584,17.387]},{"id":"xor-intro","say":"Bir kapı daha var, ve gündelik hayatta çok işe yarar: ÖZEL VEYA. İkisinden biri, ama ikisi birden değil, anlamına gelir.","at":366.895,"dur":10.463,"marks":[0,1.626,4.528,5.91,7.478,9.432]},{"id":"xor-stairs","say":"Bir merdiven boşluğundaki lambayı düşünün: aşağıdan da, yukarıdan da açılıp kapanır. Aşağıdaki anahtarı çevirin, lamba yanar. Yukarı çıkıp oradaki anahtarı çevirin, lamba söner.","at":378.358,"dur":15.16,"marks":[0,3.373,4.692,7.315,9.639,11.195,14.228]},{"id":"xor-rule","say":"Anahtarlar farklı konumdaysa lamba yanar, aynı konumdaysa söner. İşte bu, özel veya kapısıdır.","at":394.518,"dur":8.04,"marks":[0,3.287,5.544,6.55]},{"id":"adder-intro","say":"Özel veya, toplama işleminde de karşımıza çıkar. İlk bölümde gördüğümüz gibi makine sayıları bir ve sıfırla yazar; şimdi iki biti toplayalım.","at":404.558,"dur":10.968,"marks":[0,1.108,4.384,9.147]},{"id":"adder-cases","say":"Sıfır artı sıfır, sıfır. Sıfır artı bir, bir. Bir artı sıfır, bir. Bir artı bir ise iki eder; ikili sayılarla yazınca, bir sıfır.","at":416.526,"dur":12.97,"marks":[0,1.698,2.955,4.444,5.484,6.951,7.992,10.101,12.167]},{"id":"adder-carry","say":"Yani basamağa sıfır yazılır, bir de elde kalır; tıpkı dokuz artı birde, sıfır yazıp bir elde tuttuğumuz gibi.","at":429.946,"dur":8.173,"marks":[0,2.213,3.878,5.845]},{"id":"adder-gates","say":"Şimdi sütunlara bakın. Basamağa yazılan, özel veyanın tablosudur; elde ise, VE’nin tablosu. Bir özel veya ile bir VE kapısı yan yana konunca, iki biti toplayan bir makine olur.","at":439.119,"dur":14.86,"marks":[0,2.317,3.864,6.098,7.138,9.087,12.646]},{"id":"adder-chain","say":"Bu küçük toplayıcıları arka arkaya dizince, ne kadar büyük olursa olsun iki sayı toplanabilir. Altı artı yedi, on üç. Her hesap makinesinin kalbinde, bu düzenek atar.","at":454.979,"dur":13.566,"marks":[0,3.308,7.266,8.652,9.795,12.475]},{"id":"turn-hand","say":"Şimdiye kadar anahtarları elle çevirdik. Ama bir makinenin, saniyede milyarlarca kez anahtar çevirmesi gerekir; hiçbir el buna yetişemez.","at":470.745,"dur":10.798,"marks":[0,3.375,5.017,9.041]},{"id":"turn-chain","say":"Çözüm, elle değil, elektrikle çevrilen bir anahtar bulmaktı. Böylece bir kapının çıkışı, bir sonraki kapının anahtarını çevirebilecekti; zincirleme düşünme mümkün olacaktı.","at":482.543,"dur":14.273,"marks":[0,0.987,2.146,5.732,8.109,11.819]},{"id":"turn-transistor","say":"Bu buluşun adı transistördür, ve muhtemelen yirminci yüzyılın en önemli icadıdır. Yaptığı iş kulağa sıradan gelir: küçük bir elektrik akımıyla, daha büyük bir akımı açıp kapatır.","at":497.816,"dur":13.441,"marks":[0,2.367,6.192,8.755,11.15]},{"id":"turn-faucet","say":"Bir musluğun kolu gibidir; ama kolu çeviren el değil, elektriktir.","at":512.257,"dur":5.234,"marks":[0,2.17,4.241]},{"id":"tubes-before","say":"Transistörden önce bu işi vakumlu tüpler yapıyordu: ampul boyutunda, sıcak, kırılgan, ve çok elektrik yiyen düzenekler.","at":519.491,"dur":9.821,"marks":[0,3.86,5.386,6.287,7.403]},{"id":"tubes-eniac","say":"İlk bilgisayarlardan ENIAC, on yedi bin tüple koca bir odayı doldururdu; ağırlığı otuz tona yaklaşırdı. Gücü ise, bugünkü bir cep hesap makinesinin altındaydı.","at":530.312,"dur":12.245,"marks":[0,2.212,5.49,8.202,9.228]},{"id":"tubes-small","say":"Transistör ise küçüktü, ısınmıyordu, kırılmıyordu. Ve daha da önemlisi: küçültülebiliyordu.","at":543.557,"dur":8.211,"marks":[0,2.13,3.417,5.017,6.834]},{"id":"chip-print","say":"Bir sonraki adım, transistörleri tek tek üretip birbirine lehimlemek yerine, hepsini aynı silisyum parçasının üzerine birlikte basmaktı.","at":553.768,"dur":9.984,"marks":[0,1.63,5.864]},{"id":"chip-silicon","say":"Silisyum, kumun ve taşın içinde bol bulunan bir elementtir. Kumdan arıtılır, ince dilimlere kesilir; devre ise, ışıkla bir şablondan geçirilerek, fotoğraf basar gibi bu dilimin üzerine basılır.","at":564.752,"dur":15.585,"marks":[0,1.184,5.103,6.605,8.699,9.825,12.586]},{"id":"chip-name","say":"Buna tümleşik devre, halk arasındaki adıyla çip denir. Bölümün adı da buradan gelir: mantık, sözün gerçek anlamıyla taşa kazınır.","at":581.337,"dur":10.661,"marks":[0,1.874,4.845,7.155,8.062]},{"id":"growth-intro","say":"Sonrası, insanlık tarihindeki en hızlı büyüme eğrilerinden biridir.","at":594.198,"dur":4.909,"marks":[0,1.12]},{"id":"growth-list","say":"Bin dokuz yüz yetmişlerin bir işlemcisinde, birkaç bin transistör vardı. İki binlerin bir işlemcisinde, birkaç yüz milyon. Bugünün bir telefon işlemcisinde ise, on milyarlarca.","at":600.107,"dur":14.991,"marks":[0,3.481,6.276,8.816,10.927,13.864]},{"id":"growth-doubling","say":"Bu sayı, kabaca her iki yılda bir ikiye katlandı. İlk bölümdeki lambalarda gördüğümüz gibi, katlamalar birikince, sezgimiz yine yanılır.","at":616.098,"dur":10.835,"marks":[0,1.001,4.28,7.44,9.332]},{"id":"scale-people","say":"Bu sayıyı somutlaştırmak zordur; şöyle deneyelim. Türkiye’nin nüfusu, seksen beş milyon civarındadır.","at":628.933,"dur":8.89,"marks":[0,2.726,4.618,6.586]},{"id":"scale-phone","say":"Cebinizdeki telefonun işlemcisinde, Türkiye nüfusunun yüzden fazla katı sayıda anahtar vardır; ve hepsi, bir tırnak büyüklüğündeki alana sığmıştır.","at":638.823,"dur":11.286,"marks":[0,2.934,7.309,8.418]},{"id":"scale-speed","say":"Her biri, saniyede milyarlarca kez açılıp kapanır. Bu, insan elinin yaptığı en yoğun yapıdır.","at":651.109,"dur":7.66,"marks":[0,1.089,4.535,5.247]},{"id":"scale-mosque","say":"Süleymaniye’nin taşları sayılabilir; bir işlemcinin transistörleri sayılamaz.","at":659.769,"dur":5.883,"marks":[0,3.15]},{"id":"end-quote","say":"Bir şeyin nasıl çalıştığını bilmek, ona duyulan hayranlığı azaltmaz; hak edilmiş kılar.","at":667.852,"dur":6.707,"marks":[0,2.768,5.335]},{"id":"close-end","say":"Taşa kazınan mantık.","at":677.159,"dur":1.366,"marks":[0]}],"audio":""};
